import {ToolRegistry} from './registry.js';

describe('ToolRegistry input validation', () => {
  it('throws from register naming the tool when a static inputSchema is not valid JSON Schema', () => {
    const registry = new ToolRegistry();

    const register = () =>
      registry.register(
        {
          name: 'series_chart',
          description: 'Charts a series whose declared item type is misspelled',
          inputSchema: {
            type: 'object',
            properties: {series: {type: 'array', items: {type: 'strng'}}},
          },
        },
        async () => 'unreachable'
      );

    expect(register).toThrow(/tool 'series_chart'/);
  });
});
